array $input): string { if (is_string($server = $this->addonServer($input, 'recycle_bin', Addons::RECYCLE_BIN))) { return $server; } $response = $this->api()->get($this->at($server, 'recycle-bin')); if (!$response->ok()) { return $this->record('recycle_bin', $input, false, $response->error()); } $items = (array) ($response->json['items'] ?? []); return $this->record('recycle_bin', $input, true, count($items) . ' item(s) in the bin, kept ' . ($response->json['retention_days'] ?? '?') . ' days.', array_slice($items, 0, 100)); } private function restoreFromBin(array $input): string { if (is_string($server = $this->addonServer($input, 'restore_from_bin', Addons::RECYCLE_BIN))) { return $server; } if ($input['all'] ?? false) { $response = $this->api()->post($this->at($server, 'recycle-bin/restore')); } elseif (is_numeric($input['item'] ?? null)) { $response = $this->api()->post($this->at($server, 'recycle-bin/' . (int) $input['item'] . '/restore')); } else { return $this->record('restore_from_bin', $input, false, 'Name an item from recycle_bin, or set all.'); } if (!$response->ok()) { return $this->record('restore_from_bin', $input, false, $response->error()); } return $this->record('restore_from_bin', $input, true, isset($response->json['path']) ? 'Restored to ' . $response->json['path'] . '.' : 'Restored ' . ($response->json['restored'] ?? 0) . ' item(s)' . (($response->json['failed'] ?? 0) > 0 ? ', ' . $response->json['failed'] . ' could not be.' : '.')); } private function eggOptions(array $input): string { if (is_string($server = $this->addonServer($input, 'egg_options', Addons::EGG_SWITCHER))) { return $server; } $response = $this->api()->get($this->at($server, 'egg-switcher')); if (!$response->ok()) { return $this->record('egg_options', $input, false, $response->error()); } return $this->record('egg_options', $input, true, 'What this server may switch to.', $response->json); } private function switchEgg(array $input): string { if (is_string($server = $this->addonServer($input, 'switch_egg', Addons::EGG_SWITCHER))) { return $server; } $response = $this->api()->post($this->at($server, 'egg-switcher'), ['egg' => (string) ($input['egg'] ?? '')]); if (!$response->ok()) { return $this->record('switch_egg', $input, false, $response->error()); } return $this->record('switch_egg', $input, true, (string) ($response->json['message'] ?? 'The server is being rebuilt.')); } private function api(): PanelApi { return $this->api ??= new PanelApi($this->user, $this->ip); } private function at(Server $server, string $path = ''): string { return 'servers/' . $server->uuid . ($path === '' ? '' : '/' . $path); } private function owned(array $input, string $tool, ?string $permission = null): Server|string { $identifier = trim((string) ($input['server'] ?? '')); if ($identifier === '') { return $this->record($tool, $input, false, 'No server was named. Use an identifier from the list in your instructions.'); } $server = $this->user->accessibleServers() ->where(fn ($query) => $query->where('servers.uuidShort', $identifier)->orWhere('servers.uuid', $identifier)) ->first(); if ($server === null && $this->user->root_admin) { $server = Server::query()->where('uuidShort', $identifier)->orWhere('uuid', $identifier)->first(); } if ($server === null) { return $this->record($tool, $input, false, "There is no server called {$identifier} on this account. Use an identifier from the list in your instructions."); } if ($permission !== null && !$this->user->can($permission, $server)) { return $this->record($tool, $input, false, "They do not have the {$permission} permission on {$server->name}, so this cannot be done for them."); } if ($server->isSuspended()) { return $this->record($tool, $input, false, "{$server->name} is suspended. Nothing can be done to it."); } if ($server->status === Server::STATUS_INSTALL_FAILED) { return $this->record($tool, $input, false, "{$server->name}'s install failed. It has to be reinstalled from its Settings tab, and the console shows why it failed."); } if (!$server->isInstalled()) { return $this->record($tool, $input, false, "{$server->name} is still installing. Wait for that to finish."); } return $server; } private function addonServer(array $input, string $tool, string $addon): Server|string { if (is_string($server = $this->owned($input, $tool))) { return $server; } if (!Addons::appliesTo($addon, $server)) { $name = Addons::CATALOGUE[$addon]['name'] ?? $addon; return $this->record($tool, $input, false, "The {$name} is not turned on for {$server->name}'s game (" . ($server->egg?->name ?? 'unknown egg') . '), so this cannot be done there.'); } return $server; } private function kindServer(array $input, string $tool): array|string { $kind = self::KINDS[(string) ($input['kind'] ?? '')] ?? null; if ($kind === null) { return $this->record($tool, $input, false, 'kind must be one of: ' . implode(', ', $this->availableKinds() ?: array_keys(self::KINDS)) . '.'); } if (is_string($server = $this->addonServer($input, $tool, $kind['addon']))) { return $server; } return [$server, $kind]; } private function addonsOf(Server $server): array { foreach ($this->servers() as $entry) { if ($entry['identifier'] === $server->uuidShort) { return $entry['addons']; } } return array_values(array_filter(array_keys(self::UTILITIES), fn (string $addon) => Addons::appliesTo($addon, $server))); } private function contents(Server $server, string $path): string|PanelResponse { $response = $this->api()->get($this->at($server, 'files/contents'), ['file' => $path]); return $response->ok() ? $response->body : $response; } private function listing(array $input, string $tool, string $path, callable $map, string $noun): string { if (is_string($server = $this->owned($input, $tool))) { return $server; } $response = $this->api()->get($this->at($server, $path)); if (!$response->ok()) { return $this->record($tool, $input, false, $response->error()); } $rows = array_map($map, $response->items()); return $this->record($tool, $input, true, count($rows) . " {$noun}.", $rows); } private function results(string $tool, array $input, PanelResponse $response): string { if (!$response->ok()) { return $this->record($tool, $input, false, $response->error()); } $error = $response->json['error'] ?? null; $results = array_map(fn (array $row) => $this->trimRow($row, ['icon', 'authorUrl', 'url', 'updatedAt', 'stars', 'logo', 'thumbnail', 'screenshot', 'screenshots']), (array) ($response->json['results'] ?? [])); if ($results === [] && is_string($error) && $error !== '') { return $this->record($tool, $input, false, $error); } return $this->record($tool, $input, true, count($results) . ' result(s)' . (($response->json['hasMore'] ?? false) ? ', more on the next page.' : '.'), $results); } private function trimRow(array $row, array $drop): array { $out = []; foreach ($row as $key => $value) { if (in_array($key, $drop, true) || $value === null || $value === '' || $value === []) { continue; } $out[$key] = is_string($value) ? Str::limit($value, 300) : $value; } return $out; } private function playerUuid(Server $server, string $player): ?string { $player = trim($player); if (preg_match('/^[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}$/i', $player) === 1) { $hex = strtolower(str_replace('-', '', $player)); return substr($hex, 0, 8) . '-' . substr($hex, 8, 4) . '-' . substr($hex, 12, 4) . '-' . substr($hex, 16, 4) . '-' . substr($hex, 20); } foreach ($this->api()->get($this->at($server, 'players'))->items() as $row) { if (strcasecmp((string) ($row['name'] ?? ''), $player) === 0 && is_string($row['uuid'] ?? null)) { return $row['uuid']; } } return null; } private function dimension(Server $server, array $input): array|string { $world = $this->path($input['world'] ?? ''); if ($world === '/') { return 'No world folder was named.'; } $response = $this->api()->get($this->at($server, 'world-viewer/dimensions'), ['path' => $world]); if (!$response->ok()) { return $response->error(); } $all = array_values(array_filter((array) ($response->json['dimensions'] ?? []), fn (mixed $row) => is_array($row) && isset($row['path']))); if ($all === []) { return "{$world} has no dimensions with region files. Is it a world folder?"; } $wanted = strtolower(trim((string) ($input['dimension'] ?? ''))); if ($wanted === '' || $wanted === 'overworld' || $wanted === 'minecraft:overworld') { return [$all[0], $all]; } $wanted = str_replace(['minecraft:', 'the_'], ['', ''], $wanted); foreach ($all as $row) { $name = strtolower((string) ($row['name'] ?? '')); if (str_contains(str_replace('the ', '', $name), $wanted) || str_contains(strtolower((string) $row['path']), $wanted)) { return [$row, $all]; } } return "{$world} has no dimension called {$wanted}. It has: " . implode(', ', array_column($all, 'name')) . '. ' . 'On Paper and Spigot the Nether and the End are worlds of their own, such as /world_nether and /world_the_end; list_worlds shows them.'; } private function wait(array $input): void { $seconds = max(0, min(self::MAX_WAIT, (int) ($input['wait_seconds'] ?? 0))); if ($seconds > 0) { $this->pause($seconds); } } private function tail(Server $server, int $lines): string { if (!$this->user->can('websocket.connect', $server)) { return '(they cannot see this server\'s console)'; } $tail = $this->logs->tail($server, $lines); return $tail === null ? '(the console could not be read)' : ($tail === [] ? '(nothing printed yet)' : implode("\n", $tail)); } private function record(string $tool, array $input, bool $ok, string $summary, mixed $payload = null): string { $this->failed = !$ok; $this->steps[] = ['tool' => $tool, 'input' => $this->redact($input), 'ok' => $ok, 'summary' => Text::summary($summary, 300)]; if (is_callable($this->onStep)) { ($this->onStep)($this->steps); } $this->checkStop(); if ($payload === null) { return Text::utf8($summary); } $body = is_string($payload) ? $payload : json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE); $limit = $tool === 'read_file' ? self::MAX_READ + 400 : self::MAX_RESULT; if (strlen($body) > $limit) { $body = mb_strcut($body, 0, $limit) . "\n[…cut short: " . (strlen($body) - $limit) . ' more characters. Ask for less at a time.]'; } return Text::utf8($summary . "\n\n" . $body); } private function redact(array $input): array { if (isset($input['contents'])) { $input['contents'] = strlen((string) $input['contents']) . ' bytes'; } if (isset($input['edits']) && is_array($input['edits'])) { $input['edits'] = count($input['edits']) . ' change(s)'; } return $input; } private function nameOf(string $identifier): string { foreach ($this->servers() as $server) { if ($server['identifier'] === $identifier) { return $server['name']; } } return $identifier !== '' ? $identifier : 'this server'; } private function address(Server $server): ?string { $allocation = $server->allocation; return $allocation === null ? null : ($allocation->alias ?: $allocation->ip) . ':' . $allocation->port; } private function path(mixed $value): string { $path = trim((string) $value); if ($path === '') { return '/'; } $parts = []; foreach (explode('/', str_replace('\\', '/', $path)) as $part) { if ($part === '' || $part === '.') { continue; } if ($part === '..') { array_pop($parts); continue; } $parts[] = $part; } return '/' . implode('/', $parts); } private function names(mixed $value): array { $names = []; foreach ((array) $value as $name) { $name = trim((string) $name); if ($name !== '' && $name !== '.' && $name !== '..' && !str_contains($name, '/')) { $names[] = $name; } } return array_slice(array_values(array_unique($names)), 0, 100); } private static function parseProperties(string $contents): array { $settings = []; foreach (preg_split('/\r\n|\n|\r/', $contents) ?: [] as $line) { if ($line === '' || str_starts_with(ltrim($line), '#') || !str_contains($line, '=')) { continue; } [$key, $value] = explode('=', $line, 2); $settings[trim($key)] = trim($value); } return $settings; } private const NBT_TYPES = [1 => 'byte', 2 => 'short', 3 => 'int', 4 => 'long', 5 => 'float', 6 => 'double', 8 => 'string']; private static function flatten(array $node, string $prefix, array &$out): void { if (count($out) >= 2000) { return; } $children = $node['children'] ?? null; if (is_array($children)) { if (($node['type'] ?? 0) === 9 && count($children) > 16) { $out[$prefix] = '[list of ' . count($children) . ']'; return; } foreach ($children as $child) { $name = (string) ($child['name'] ?? ''); self::flatten((array) $child, $prefix === '' ? $name : "{$prefix}.{$name}", $out); } return; } if ($prefix === '') { return; } $value = $node['value'] ?? null; $type = self::NBT_TYPES[(int) ($node['type'] ?? 0)] ?? null; $out[$prefix] = is_array($value) ? '[' . count($value) . ' values]' : (is_bool($value) ? ($value ? 'true' : 'false') : (string) $value) . ($type !== null ? " ({$type})" : ''); } private static function setNbt(array &$node, array $segments, mixed $value): ?string { $at = &$node; foreach ($segments as $segment) { if (!is_array($at['children'] ?? null)) { return 'there is no such path.'; } $found = false; foreach ($at['children'] as $index => $child) { if ((string) ($child['name'] ?? '') === $segment) { $at = &$at['children'][$index]; $found = true; break; } } if (!$found) { return 'there is no such path. Use a path exactly as read_level_dat shows it.'; } } $type = (int) ($at['type'] ?? 0); if (!isset(self::NBT_TYPES[$type])) { return 'only single values can be changed, not lists or compounds.'; } if (is_string($value) && $type !== 8) { $lower = strtolower(trim($value)); $value = match ($lower) { 'true' => 1, 'false' => 0, default => $value, }; } elseif (is_bool($value)) { $value = $type === 8 ? ($value ? 'true' : 'false') : (int) $value; } if ($type !== 8 && !is_numeric($value)) { return 'that value has to be a number.'; } $at['value'] = match ($type) { 1 => max(-128, min(127, (int) $value)), 2 => max(-32768, min(32767, (int) $value)), 3 => (int) $value, 4 => (string) (int) $value, 5, 6 => (float) $value, default => (string) $value, }; return null; } private function tool(string $name, string $description, array $properties, array $required = []): array { return [ 'name' => $name, 'description' => $description, 'schema' => ['type' => 'object', 'properties' => $properties === [] ? new \stdClass() : $properties, 'required' => $required], ]; } private function string(string $description): array { return ['type' => 'string', 'description' => $description]; } private function pairs(string $key, string $description): array { return ['type' => 'array', 'description' => $description, 'items' => [ 'type' => 'object', 'properties' => [$key => ['type' => 'string'], 'value' => ['type' => 'string']], 'required' => [$key, 'value'], ]]; } private static function unpair(mixed $value, string $key): array { $out = []; foreach ((array) $value as $name => $entry) { if (is_array($entry) && array_key_exists($key, $entry)) { $out[(string) $entry[$key]] = $entry['value'] ?? ''; } elseif (is_string($name) && (is_scalar($entry) || $entry === null)) { $out[$name] = $entry ?? ''; } } return $out; } private function strings(string $description): array { return ['type' => 'array', 'items' => ['type' => 'string'], 'description' => $description]; } private function integer(string $description): array { return ['type' => 'integer', 'description' => $description]; } private function boolean(string $description): array { return ['type' => 'boolean', 'description' => $description]; } private function enum(array $values, string $description): array { return ['type' => 'string', 'enum' => array_values($values), 'description' => $description]; } } 